<script>const report=@json($report);function copyReport(){navigator.clipboard.writeText(JSON.stringify(report,null,2))}function save(data,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click()}function downloadJson(){save(JSON.stringify(report,null,2),'reverse-phone-osint.json','application/json')}function downloadCsv(){const rows=[['Category','Platform','Name','Phone','Confidence','Source','Evidence'],...report.public_footprint.map(p=>[p.category,p.platform,p.name,p.phone_number,p.confidence,p.source_url,p.evidence])];save(rows.map(r=>r.map(v=>'"'+String(v||'').replaceAll('"','""')+'"').join(',')).join('\n'),'reverse-phone-osint.csv','text/csv')}</script>
